    tokens = tokenize(expr)
    return parse_expression(tokens, context)

def tokenize(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i] in ' \t\n':
            i += 1
            continue
        if expr[i] == '"':
            j = i + 1
            while j < n and expr[j] != '"':
                j += 1
            tokens.append(('string', expr[i+1:j]))
            i = j + 1
        elif expr[i] in '()+-*/%&|^~':
            tokens.append(('operator', expr[i]))
            i += 1
        elif expr[i] in '()':
            tokens.append(('paren', expr[i]))
            i += 1
        elif expr[i] in '><=!':
            tokens.append(('operator', expr[i:i+2]))
            i += 2
        elif expr[i] in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ_':
            j = i
            while j < n and expr[j] in 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_':
                j += 1
            tokens.append(('identifier', expr[i:j]))
            i = j
        else:
            j = i
            while j < n and expr[j] in '0123456789.':
                j += 1
            if expr[i:j] == '.':
                tokens.append(('operator', '.'))
                i = j
            else:
                tokens.append(('number', expr[i:j]))
                i = j
    return tokens

def parse_expression(tokens, context):
    tokens = list(tokens)
    return parse_primary(tokens, context)

def parse_primary(tokens, context):
    if not tokens:
        return None
    token = tokens.pop(0)
    if token[0] == 'string':
        return token[1]
    elif token[0] == 'number':
        return float(token[1]) if '.' in token[1] else int(token[1])
    elif token[0] == 'identifier':
        if token[1] in context:
            return context[token[1]]
        else:
            return None
    elif token[0] == 'paren':
        if tokens[0][0] == 'paren' and tokens[0][1] == ')':
            tokens.pop(0)
            return parse_expression(tokens, context)
        else:
            return parse_expression(tokens, context)
    elif token[0] == 'operator' and token[1] == 'not':
        operand = parse_primary(tokens, context)
        if operand is None:
            return None
        return not operand
    else:
        return parse_primary(tokens, context)

def parse_comparison(tokens, context):
    left = parse_primary(tokens, context)
    if left is None:
        return None
    if not tokens:
        return left
    op = tokens.pop(0)
    if op[0] == 'operator':
        if op[1] in ('==', '!=', '<', '<=', '>', '>='):
            right = parse_primary(tokens, context)
            if right is None:
                return None
            if op[1] == '==':
                return left == right
            elif op[1] == '!=':
                return left != right
            elif op[1] == '<':
                return left < right
            elif op[1] == '<=':
                return left <= right
            elif op[1] == '>':
                return left > right
            elif op[1] == '>=':
                return left >= right
    return left

def parse_and(tokens, context):
    left = parse_comparison(tokens, context)
    if left is None:
        return None
    while tokens and tokens[0][0] == 'operator' and tokens[0][1] == 'and':
        tokens.pop(0)
        right = parse_comparison(tokens, context)
        if right is None:
            return None
        left = left and right
    return left

def parse_or(tokens, context):
    left = parse_and(tokens, context)
    if left is None:
        return None
    while tokens and tokens[0][0] == 'operator' and tokens[0][1] == 'or':
        tokens.pop(0)
        right = parse_and(tokens, context)
        if right is None:
            return None
        left = left or right
    return left

def parse_expression(tokens, context):
