import json
import sys
import re

def evaluate_expression(expr, context):
    try:
        # Replace context keys with their values
        for key in context:
            expr = expr.replace(f'"{key}"', str(context[key]))
            expr = expr.replace(f'"{key.lower()}"', str(context[key]))
            expr = expr.replace(f'"{key.upper()}"', str(context[key]))
            expr = expr.replace(f'"{key.capitalize()}"', str(context[key]))

        # Evaluate the expression safely
        return eval(expr, {'__builtins__': None}, {'__': lambda x: x, 'and': lambda x, y: x and y, 'or': lambda x, y: x or y, 'not': lambda x: not x})
    except:
        return False

def parse_policy(policy_path):
    with open(policy_path, 'r') as f:
        lines = [line.strip() for line in f if line.strip() and not line.startswith('#')]
    return lines

def parse_context(context_path):
    with open(context_path, 'r') as f:
        return json.load(f)

def main():
    if len(sys.argv) != 3:
        print("Usage: python access_check.py <policy_path> <context_path>")
        sys.exit(1)

    policy_path = sys.argv[1]
    context_path = sys.argv[2]

    policy_rules = parse_policy(policy_path)
    context = parse_context(context_path)

    for rule in policy_rules:
        parts = rule.split('->')
        if len(parts) != 2:
            continue
        expr, decision = parts
        if evaluate_expression(expr, context):
            print(decision)
            sys.exit(0)

    print("deny")

if __name__ == "__main__":
    main()
